// ============================================================================
// ARM_Serial_Wire_Debug_apb: APB4 register wrapper around ARM_Serial_Wire_Debug_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/ARM_Serial_Wire_Debug.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/ARM_Serial_Wire_Debug.md
// ============================================================================
module ARM_Serial_Wire_Debug_apb #(
  parameter logic [31:0] DPIDR = 32'h0010_1001
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic swclk,
  input logic swdio_in,
  output logic swdio_out,
  output logic swdio_oe
);
  localparam logic [31:0] ID_VALUE = 32'h53570200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [10:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd11) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_cdbgpwrupreq;
  logic          c_cdbgpwrupack;
  logic          c_csyspwrupreq;
  logic          c_csyspwrupack;
  logic          c_ap_req;
  logic          c_ap_busy;
  logic          c_ap_write;
  logic [7:0]    c_ap_sel;
  logic [5:0]    c_ap_addr;
  logic [31:0]   c_ap_wdata;
  logic          c_ap_done;
  logic [31:0]   c_ap_rdata;
  logic          c_ap_err;
  logic          c_ap_abort;
  logic          c_lockout;
  logic          c_line_reset;
  logic          c_proto_err;
  logic          c_ack_wait;
  logic          c_ack_fault;
  ARM_Serial_Wire_Debug_top #(.DPIDR(DPIDR)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .swclk(swclk),
    .swdio_in(swdio_in),
    .swdio_out(swdio_out),
    .swdio_oe(swdio_oe),
    .cdbgpwrupreq(c_cdbgpwrupreq),
    .cdbgpwrupack(c_cdbgpwrupack),
    .csyspwrupreq(c_csyspwrupreq),
    .csyspwrupack(c_csyspwrupack),
    .ap_req(c_ap_req),
    .ap_busy(c_ap_busy),
    .ap_write(c_ap_write),
    .ap_sel(c_ap_sel),
    .ap_addr(c_ap_addr),
    .ap_wdata(c_ap_wdata),
    .ap_done(c_ap_done),
    .ap_rdata(c_ap_rdata),
    .ap_err(c_ap_err),
    .ap_abort(c_ap_abort),
    .lockout(c_lockout),
    .line_reset(c_line_reset),
    .proto_err(c_proto_err),
    .ack_wait(c_ack_wait),
    .ack_fault(c_ack_fault)
  );

  // ---------------- registers ----------------
  logic [6:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [1:0] r_PWR;   // 12'h014 PWR
  logic [31:0] h_APREQ0;   // 12'h018 APREQ0 holding register
  logic [14:0] h_APREQ1;   // 12'h01C APREQ1 holding register
  logic [31:0] h_APRESP0;   // 12'h020 APRESP0 holding register
  logic [0:0] h_APRESP1;   // 12'h024 APRESP1 holding register
  logic avail_APREQ;
  logic vld_APRESP;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_PWR <= 2'h0;
      h_APREQ0 <= '0;
      h_APREQ1 <= '0;
      h_APRESP0 <= '0;
      h_APRESP1 <= '0;
      avail_APREQ <= 1'b0;
      vld_APRESP <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[6:0] & wmask[6:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[6:0]) | (PWDATA[6:0] & wmask[6:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_PWR <= (r_PWR & ~wmask[1:0]) | (PWDATA[1:0] & wmask[1:0]);
      if (c_ap_req && (!avail_APREQ || (rd && hit[7]))) begin
        h_APREQ0[31:0] <= c_ap_wdata[31:0];
        h_APREQ1[0:0] <= c_ap_write;
        h_APREQ1[8:1] <= c_ap_sel[7:0];
        h_APREQ1[14:9] <= c_ap_addr[5:0];
        avail_APREQ <= 1'b1;
      end else if (rd && hit[7]) avail_APREQ <= 1'b0;
      if (wr && hit[8]) h_APRESP0 <= (h_APRESP0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[9]) h_APRESP1 <= (h_APRESP1 & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      vld_APRESP <= wr && hit[9];
    end
  end

  // ---------------- core inputs ----------------
  assign c_cdbgpwrupack = r_PWR[0:0];
  assign c_csyspwrupack = r_PWR[1:1];
  assign c_ap_rdata[31:0] = h_APRESP0[31:0];
  assign c_ap_err = h_APRESP1;
  assign c_ap_done = vld_APRESP;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_line_reset;
    irq_set[1] = c_proto_err;
    irq_set[2] = c_ack_wait;
    irq_set[3] = c_ack_fault;
    irq_set[4] = c_ap_abort;
    irq_set[5] = c_ap_req & (~avail_APREQ | (rd & hit[7]));
    irq_set[6] = c_ap_req & avail_APREQ & ~(rd & hit[7]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [0:0] flags = {avail_APREQ};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_PWR);
      10'd6: apb_rdata = 32'(h_APREQ0);
      10'd7: apb_rdata = 32'(h_APREQ1);
      10'd8: apb_rdata = 32'(h_APRESP0);
      10'd9: apb_rdata = 32'(h_APRESP1);
      10'd10: apb_rdata = 32'({c_csyspwrupreq, c_cdbgpwrupreq, c_lockout, c_ap_busy});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
